map "https://fhir.hl7.at/elga/cda2fhir/r4/StructureMap/at-cda-lab-to-fhir-bundle" = "CdaLabToFhirBundle"

//
// Mapping CDA2FHIR
//

conceptmap "cda-lab-clinicaldocument-code-2-fhir-category" {
  prefix s = "http://loinc.org"

  s: "11502-2" == s: "26436-6"
  s: "18725-2" == s: "18725-2"
}

conceptmap "cda-sdtc-statuscode-2-fhir-diagnosticreport-status" {
  prefix s = "http://terminology.hl7.org/CodeSystem/v3-ActStatus"
  prefix t = "http://hl7.org/fhir/diagnostic-report-status"

  s:"active" == t:"preliminary"
  s:"nullified" == t:"entered-in-error"
}

